CONTRACT
  CONTRACT = JSON.parse(CONTRACT_JSON)

  # Every method reaches #handle, so nothing is answered by WEBrick on the fake's behalf.
  class Servlet < WEBrick::HTTPServlet::AbstractServlet
    def initialize(server, fake)
      super(server)
      @fake = fake
    end

    def service(req, res) = @fake.handle(req, res)
  end

  attr_reader :port

  def initialize
    @routes = CONTRACT.fetch("routes")
    @mutex = Mutex.new
    @requests = []
    @covered = {}
    @violations = []
    @overrides = {}
    ready = Queue.new
    @server = WEBrick::HTTPServer.new(BindAddress: "127.0.0.1", Port: 0, StartCallback: -> { ready << true },
                                      Logger: WEBrick::Log.new(File::NULL), AccessLog: [])
    @server.mount("/", Servlet, self)
    @port = @server.listeners[0].addr[1]
    @thread = Thread.new { @server.start }
    # A shutdown that lands before start would leave the server running for the rest of the process.
    ready.pop
  end

  def shutdown
    @server.shutdown
    @thread.join(2)
  end

  # The contract's routes, "METHOD /path", in contract order.
  def route_keys = @routes.map { |r| r["key"] }

  # This SDK's recorded reason for not reaching a route, or nil.
  def waived(key) = route(key)["waived"]

  # A route's golden by name; nil is the first, the success example the fake serves.
  def golden(key, name = nil)
    goldens = route(key)["goldens"]
    g = name.nil? ? goldens.first : goldens.find { |x| x["name"] == name }
    raise ArgumentError, "#{key} has no golden #{name.inspect}" if g.nil?

    g
  end

  # Makes the fake answer a route with one of its other goldens.
  def use_golden(key, name)
    answer = golden(key, name)["response"]
    @mutex.synchronize { @overrides[key] = answer }
  end

  # Makes the fake answer a route with a custom response, which must still be one the contract
  # allows: a declared status, and a JSON body inside its schema.
  def respond(key, status, body = "")
    r = route(key)
    decl = r["responses"][status.to_s]
    raise ArgumentError, "#{key} never answers #{status}; the contract declares #{r['responses'].keys.sort}" if decl.nil?

    ctype = decl["contentType"].to_s
    answer = { "status" => status, "headers" => {} }
    if body.empty?
      # no body
    elsif json_type?(ctype)
      value = begin
        JSON.parse(body)
      rescue JSON::ParserError => e
        raise ArgumentError, "#{key} #{status}: the body is not JSON: #{e.message}"
      end
      if decl.key?("schema")
        bad = validate(decl["schema"], value, "$")
        raise ArgumentError, "#{key} #{status}: the launcher can never send this body: #{bad}" unless bad.empty?
      end
      answer["body"] = value
    elsif !ctype.empty?
      answer["bodyText"] = body
    else
      raise ArgumentError, "#{key} #{status} has no body in the contract"
    end
    answer["headers"]["Content-Type"] = ctype unless ctype.empty?
    @mutex.synchronize { @overrides[key] = answer }
  end

  # Whether any request reached the route.
  def covered?(key) = @mutex.synchronize { @covered.key?(key) }

  # Every request, in order: {method:, path:, query:, headers:, body:, route:}.
  def received = @mutex.synchronize { @requests.dup }

  # Every way a request broke the contract.
  def violations = @mutex.synchronize { @violations.dup }

  # Fails the test for every contract violation the fake saw.
  def assert_conforms(test)
    test.assert_empty(violations, "requests broke the launcher contract")
  end

  def handle(req, res)
    body = read_body(req)
    path = req.path
    method = req.request_method
    query = URI.decode_www_form(req.query_string.to_s).to_h
    headers = req.header.transform_values { |v| v.join(", ") }
    record = { method: method, path: path, query: query, headers: headers, body: body, route: nil }
    hit = nil
    allow = []
    @routes.each do |r|
      next unless path_matches?(r["path"], path)

      if r["method"] == "ANY" || r["method"] == method
        hit = r
        break
      end
      allow << r["method"]
    end
    @mutex.synchronize do
      if hit.nil?
        @requests << record
        @violations << "#{method} #{path}: the launcher serves no such route"
        if allow.empty?
          text(res, 404, "404 page not found\n")
        else
          res["Allow"] = allow.join(", ")
          text(res, 405, "Method Not Allowed\n")
        end
        return
      end
      record[:route] = hit["key"]
      @requests << record
      @covered[hit["key"]] = true
      request_violations(hit, method, path, query, req, body).each { |v| @violations << "#{method} #{path}: #{v}" }
      answer = @overrides[hit["key"]] || choose(hit, method)
      write(res, answer)
    end
  end

  private

  def route(key)
    r = @routes.find { |x| x["key"] == key }
    raise ArgumentError, "the contract has no route #{key.inspect}" if r.nil?

    r
  end

  # WEBrick refuses a bodyless POST or PUT with 411; the launcher reads it as an empty body.
  def read_body(req)
    req.body.to_s
  rescue WEBrick::HTTPStatus::LengthRequired
    ""
  end

  def choose(route, method)
    route["goldens"].each do |g|
      m = g["request"]["method"] || route["servedMethod"]
      return g["response"] if m == method
    end
    route["goldens"].first["response"]
  end

  def write(res, answer)
    res.status = answer["status"]
    (answer["headers"] || {}).each { |k, v| res[k] = v }
    if answer.key?("body")
      res.body = JSON.generate(answer["body"])
    elsif answer.key?("bodyText")
      res.body = answer["bodyText"]
    end
  end

  def text(res, status, body)
    res.status = status
    res["Content-Type"] = "text/plain; charset=utf-8"
    res["X-Content-Type-Options"] = "nosniff"
    res.body = body
  end

  def request_violations(route, method, path, query, req, body)
    out = []
    request = route["request"] || {}
    if route["method"] == "ANY" && method != route["servedMethod"]
      out << "the route serves #{route['servedMethod']}, not #{method}"
    end
    (request["headers"] || {}).keys.sort.each do |name|
      out << "missing required header #{name}" if request["headers"][name]["required"] && req[name].to_s.empty?
    end
    query.keys.sort.each do |k|
      schema = (request["query"] || {})[k]
      if schema.nil?
        out << "query parameter #{k} is not in the contract"
      else
        out.concat(validate(schema, query[k], "query parameter #{k}"))
      end
    end
    want = route["path"].delete_prefix("/").delete_suffix("/").split("/", -1)
    got = path.delete_prefix("/").delete_suffix("/").split("/", -1)
    want.each_with_index do |seg, i|
      next unless i < got.size && seg.start_with?("{")

      name = seg.delete("{}")
      schema = (request["params"] || {})[name]
      out.concat(validate(schema, got[i], "path parameter #{name}")) if schema
    end
    out.concat(body_violations(request, body))
  end

  def body_violations(request, body)
    schema = request["body"]
    if schema.nil?
      return body.empty? ? [] : ["the route takes no body"]
    end
    return request["optionalBody"] ? [] : ["the route requires a body"] if body.empty?

    value = begin
      JSON.parse(body)
    rescue JSON::ParserError => e
      return ["body is not JSON: #{e.message}"]
    end
    validate(schema, value, "body")
  end

  def path_matches?(pattern, path)
    want = pattern.delete_prefix("/").delete_suffix("/").split("/", -1)
    got = path.delete_prefix("/").delete_suffix("/").split("/", -1)
    return false unless want.size == got.size

    want.zip(got).all? { |w, g| w.start_with?("{") ? !g.empty? : w == g }
  end

  def json_type?(content_type) = content_type.split(";").first.to_s.strip == "application/json"

  # Checks v against the contract's JSON Schema subset: type, properties, required,
  # additionalProperties, items, enum, minLength, maxLength.
  def validate(schema, v, at)
    return ["#{at}: malformed schema"] unless schema.is_a?(Hash)
    return ["#{at}: is #{json_type(v)}, want #{schema['type']}"] if schema.key?("type") && !type_matches?(schema["type"], v)

    out = []
    if schema.key?("enum") && schema["enum"].none? { |e| e == v }
      out << "#{at}: #{JSON.generate(v)} is not one of #{JSON.generate(schema['enum'])}"
    end
    out.concat(string_violations(schema, v, at)) if v.is_a?(String)
    out.concat(object_violations(schema, v, at)) if v.is_a?(Hash)
    if v.is_a?(Array) && schema.key?("items")
      v.each_with_index { |e, i| out.concat(validate(schema["items"], e, "#{at}[#{i}]")) }
    end
    out
  end

  def string_violations(schema, str, at)
    out = []
    out << "#{at}: #{str.inspect} is shorter than #{schema['minLength']}" if schema["minLength"] && str.length < schema["minLength"]
    out << "#{at}: #{str.inspect} is longer than #{schema['maxLength']}" if schema["maxLength"] && str.length > schema["maxLength"]
    out
  end

  def object_violations(schema, obj, at)
    out = []
    (schema["required"] || []).each do |name|
      out << "#{at}: missing required property #{name.inspect}" unless obj.key?(name)
    end
    props = schema["properties"] || {}
    obj.keys.sort.each do |k|
      if props.key?(k)
        out.concat(validate(props[k], obj[k], "#{at}.#{k}"))
        next
      end
      ap = schema["additionalProperties"]
      if ap == false
        out << "#{at}: property #{k.inspect} is not in the contract"
      elsif ap.is_a?(Hash)
        out.concat(validate(ap, obj[k], "#{at}.#{k}"))
      end
    end
    out
  end

  def type_matches?(type, v)
    Array(type).any? { |t| type?(t, v) }
  end

  def type?(type, v)
    case type
    when "integer" then v.is_a?(Integer) || (v.is_a?(Float) && v.finite? && v == v.floor)
    when "number" then v.is_a?(Integer) || v.is_a?(Float)
    else json_type(v) == type
    end
  end

  def json_type(v)
    case v
    when nil then "null"
    when true, false then "boolean"
    when Integer, Float then "number"
    when String then "string"
    when Array then "array"
    when Hash then "object"
    else v.class.name
    end
  end
end
